+        String sanitized = description.replaceAll("[^A-Za-z0-9]+", "_");
+        int prefixLength = Math.min(sanitized.length(), Math.max(0, 200 - lastWord.length() - digest.length() - 2));
+        String prefix = sanitized.substring(0, prefixLength);
+        while (prefix.endsWith("_")) {
+            prefix = prefix.substring(0, prefix.length() - 1);
+        }
+        String result = prefix + (prefix.isEmpty() ? "" : "-") + lastWord + "-" + digest;
+        // This is defensive for descriptions containing an unusually long final word.
+        return result.substring(0, Math.min(200, result.length()));
+    }
+
+    private static String digest(String value) {
+        try {
+            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(UTF_8));
+            StringBuilder result = new StringBuilder(digest.length * 2);
+            for (byte element : digest) {
+                result.append(String.format("%02x", element & 0xff));
+            }
+            return result.toString();
+        } catch (NoSuchAlgorithmException e) {
+            throw new IllegalStateException(e);
+        }
+    }
+
+    private FileSyncedProperties getOrCreateStoredRules(File storedRulesFile, boolean materialize) {
+        try {
+            return STORED_RULES_BY_PATH.computeIfAbsent(storedRulesFile.getCanonicalPath(), path -> new FileSyncedProperties(storedRulesFile, materialize));
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private File getStoredRulesFile() {
+        if (existsWithoutFollowingLinks(storeFolder) && !storeFolder.isDirectory()) {
+            throw new StoreInitializationFailedException(String.format("Store path is not a directory: %s", storeFolder.getAbsolutePath()));
+        }
+        File rulesFile = new File(storeFolder, STORED_RULES_FILE_NAME);
+        if (!existsWithoutFollowingLinks(rulesFile) && !storeCreationAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+        }
+        return rulesFile;
+    }
+
+    private void checkIndexLocation(File storedRulesFile) {
+        if (existsWithoutFollowingLinks(storedRulesFile) && !Files.isRegularFile(storedRulesFile.toPath(), LinkOption.NOFOLLOW_LINKS)) {
+            throw new StoreInitializationFailedException(String.format(
+                    "The violation store index must be a regular file directly in the store folder: %s",
+                    storedRulesFile.getAbsolutePath()));
+        }
+    }
+
+    private void checkInitialization(boolean initializationSuccessful, String message, Object... args) {
+        if (!initializationSuccessful) {
+            throw new StoreInitializationFailedException(String.format(message, args));
+        }
+    }
+
+    private void checkIntegrity() {
+        IntegrityReport report = inspectIntegrity();
+        if (integrityMode == IntegrityMode.FAIL && report.hasProblems()) {
+            throw new StoreInitializationFailedException(report.message());
+        }
+        if (integrityMode == IntegrityMode.REPAIR) {
+            repair(report);
+        }
+    }
+
+    private IntegrityReport inspectIntegrity() {
+        List<IntegrityEntry> entries = new ArrayList<>();
+        for (Map.Entry<String, String> property : storedRules.entries()) {
+            entries.add(new IntegrityEntry(property.getKey(), property.getValue()));
+        }
+        Collections.sort(entries, Comparator.comparing(entry -> entry.description));
+
+        Path folder = storeFolder.toPath().toAbsolutePath().normalize();
+        Path realFolder = realFolder(folder);
+        Map<String, List<IntegrityEntry>> byRecordedName = new HashMap<>();
+        Map<String, List<IntegrityEntry>> byResolvedFile = new HashMap<>();
+        Map<String, List<IntegrityEntry>> byDerivedName = new HashMap<>();
+
+        for (IntegrityEntry entry : entries) {
+            entry.recordedPath = folder.resolve(entry.recordedName).normalize();
+            entry.derivedName = deriveNameForIntegrity(entry.description);
+            entry.resolvedPath = resolveEntryPath(entry, folder, realFolder);
+            if (entry.resolvedPath != null) {
+                entry.empty = readLines(entry.resolvedPath.toFile()).isEmpty();
+                entry.resolvedFileKey = fileKey(entry.resolvedPath);
+            }
+            byRecordedName.computeIfAbsent(entry.recordedName, __ -> new ArrayList<>()).add(entry);
+            if (entry.resolvedPath != null) {
+                String key = entry.resolvedFileKey == null ? entry.resolvedPath.toString() : entry.resolvedFileKey;
+                byResolvedFile.computeIfAbsent(key, __ -> new ArrayList<>()).add(entry);
+            }
+            byDerivedName.computeIfAbsent(entry.derivedName, __ -> new ArrayList<>()).add(entry);
+        }
+
+        for (IntegrityEntry entry : entries) {
+            entry.shared = byRecordedName.get(entry.recordedName).size() > 1;
+            if (entry.resolvedPath != null) {
+                String key = entry.resolvedFileKey == null ? entry.resolvedPath.toString() : entry.resolvedFileKey;
+                entry.shared |= byResolvedFile.get(key).size() > 1;
+            }
+            entry.misplaced = !entry.recordedName.equals(entry.derivedName);
+            entry.colliding = byDerivedName.get(entry.derivedName).size() > 1;
+            entry.occupied = isOccupied(entry, entries, folder, realFolder);
+        }
+
+        List<Path> unownedFiles = findUnownedFiles(entries, folder);
+        return new IntegrityReport(entries, unownedFiles);
+    }
+
+    private String deriveNameForIntegrity(String description) {
+        return checkedStrategyName(description, true);
+    }
+
+    private String checkedStrategyName(String description, boolean duringInitialization) {
+        String result;
+        try {
+            result = ruleViolationFileNameStrategy.createRuleFileName(description);
+        } catch (RuntimeException e) {
+            if (duringInitialization) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Could not derive a violation file name for rule '%s'", description), e);
+            }
+            throw e;
+        }
+        if (result == null || result.trim().isEmpty()) {
+            String message = String.format("RuleViolationFileNameStrategy returned no name for rule '%s'", description);
+            if (duringInitialization) {
+                throw new StoreInitializationFailedException(message);
+            }
+            throw new StoreUpdateFailedException(message);
+        }
+        return result;
+    }
+
+    private Path resolveEntryPath(IntegrityEntry entry, Path folder, Path realFolder) {
+        if (entry.recordedName.equals(STORED_RULES_FILE_NAME)) {
+            entry.broken = true;
+            return null;
+        }
+        if (!entry.recordedPath.startsWith(folder)) {
+            entry.broken = true;
+            return null;
+        }
+        if (!existsWithoutFollowingLinks(entry.recordedPath.toFile())) {
+            entry.broken = true;
+            return null;
+        }
+        try {
+            Path resolved = entry.recordedPath.toRealPath();
+            if (!resolved.startsWith(realFolder) || !realFolder.equals(resolved.getParent()) ||
+                    !Files.isRegularFile(resolved, LinkOption.NOFOLLOW_LINKS)) {
+                entry.broken = true;
+                return null;
+            }
+            return resolved;
+        } catch (IOException e) {
+            entry.broken = true;
+            return null;
+        }
+    }
+
+    private boolean isOccupied(IntegrityEntry entry, List<IntegrityEntry> entries, Path folder, Path realFolder) {
+        for (IntegrityEntry other : entries) {
+            if (other != entry && other.recordedName.equals(entry.derivedName)) {
+                return true;
+            }
+        }
+        Path destination = folder.resolve(entry.derivedName).normalize();
+        if (!destination.startsWith(folder) || destination.equals(folder.resolve(STORED_RULES_FILE_NAME))) {
+            return true;
+        }
+        if (!existsWithoutFollowingLinks(destination.toFile())) {
+            return false;
+        }
+        // A correctly placed entry owns its own destination. A misplaced entry
+        // must never replace anything that is already there.
+        if (!entry.misplaced && entry.recordedPath.equals(destination)) {
+            return false;
+        }
+        try {
+            Path resolved = destination.toRealPath();
+            return !resolved.startsWith(realFolder) || !realFolder.equals(resolved.getParent()) ||
+                    !Files.isRegularFile(resolved, LinkOption.NOFOLLOW_LINKS) ||
+                    entry.resolvedPath == null || !resolved.equals(entry.resolvedPath);
+        } catch (IOException e) {
+            return true;
+        }
+    }
+
+    private List<Path> findUnownedFiles(List<IntegrityEntry> entries, Path folder) {
+        List<Path> result = new ArrayList<>();
+        if (!Files.isDirectory(folder)) {
+            return result;
+        }
+        try (DirectoryStream<Path> files = Files.newDirectoryStream(folder)) {
+            for (Path file : files) {
+                if (STORED_RULES_FILE_NAME.equals(file.getFileName().toString()) ||
+                        !Files.isRegularFile(file, LinkOption.NOFOLLOW_LINKS)) {
+                    continue;
+                }
+                Path realFile = file.toRealPath();
+                boolean owned = entries.stream().anyMatch(entry -> realFile.equals(entry.resolvedPath));
+                if (!owned) {
+                    result.add(file);
+                }
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        result.sort(Comparator.comparing(path -> path.getFileName().toString()));
+        return result;
+    }
+
+    private Path realFolder(Path folder) {
+        try {
+            return Files.exists(folder) ? folder.toRealPath() : folder;
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private String fileKey(Path path) {
+        try {
+            BasicFileAttributes attributes = Files.readAttributes(path, BasicFileAttributes.class);
+            return attributes.fileKey() == null ? null : attributes.fileKey().toString();
+        } catch (IOException e) {
+            return null;
+        }
+    }
+
+    private void repair(IntegrityReport report) {
+        boolean indexChanged = false;
+        for (IntegrityEntry entry : report.entries) {
+            // Shared entries are deliberately opaque to repair. This also gives
+            // sharing precedence over every other condition.
+            if (entry.shared) {
+                continue;
+            }
+            if (entry.broken) {
+                storedRules.removeInMemory(entry.description);
+                indexChanged = true;
+            } else if (entry.empty) {
+                storedRules.removeInMemory(entry.description);
+                deleteEntryFile(entry);
+                indexChanged = true;
+            } else if (entry.misplaced && !entry.colliding && !entry.occupied) {
+                moveEntryFile(entry);
+                storedRules.setInMemory(entry.description, entry.derivedName);
+                indexChanged = true;
+            }
+        }
+        if (indexChanged) {
+            storedRules.syncFileSystemAsInitialization();
+        }
+    }
+
+    private void deleteEntryFile(IntegrityEntry entry) {
+        if (entry.resolvedPath == null) {
+            return;
+        }
+        try {
+            Files.deleteIfExists(entry.resolvedPath);
+            if (!entry.recordedPath.equals(entry.resolvedPath) && Files.isSymbolicLink(entry.recordedPath)) {
+                Files.deleteIfExists(entry.recordedPath);
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not remove resolved violation file for rule '%s'", entry.description), e);
+        }
+    }
+
+    private void moveEntryFile(IntegrityEntry entry) {
+        Path destination = storeFolder.toPath().toAbsolutePath().normalize().resolve(entry.derivedName).normalize();
+        try {
+            if (!entry.resolvedPath.equals(destination)) {
+                Files.move(entry.resolvedPath, destination);
+            }
+            if (!entry.recordedPath.equals(entry.resolvedPath) && Files.isSymbolicLink(entry.recordedPath)) {
+                Files.deleteIfExists(entry.recordedPath);
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not move violation file for rule '%s' to '%s'", entry.description, entry.derivedName), e);
+        }
+    }
+
+    @Override
+    public boolean contains(ArchRule rule) {
+        return storedRules.containsKey(rule.getDescription());
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        synchronized (storedRules) {
+            String description = rule.getDescription();
+            String existingFileName = storedRules.getProperty(description);
+            if (integrityMode == IntegrityMode.REPAIR && violations.isEmpty()) {
+                if (existingFileName != null) {
+                    forgetKnownRule(description, existingFileName);
+                }
+                return;
+            }
+
+            String ruleFileName = existingFileName != null
+                    ? existingFileName
+                    : checkedStrategyName(description, false);
+            validateSaveTarget(description, ruleFileName, existingFileName != null);
+            if (existingFileName == null) {
+                storedRules.setInMemory(description, ruleFileName);
+            }
+            write(violations, new File(storeFolder, ruleFileName));
+            if (existingFileName == null) {
+                storedRules.syncFileSystem();
+            }
+        }
+    }
+
+    private void forgetKnownRule(String description, String fileName) {
+        if (!isSharedFile(description, fileName)) {
+            IntegrityEntry entry = new IntegrityEntry(description, fileName);
+            Path folder = storeFolder.toPath().toAbsolutePath().normalize();
+            entry.recordedPath = folder.resolve(fileName).normalize();
+            entry.resolvedPath = resolveEntryPath(entry, folder, realFolder(folder));
+            deleteEntryFile(entry);
+        }
+        storedRules.removeInMemory(description);
+        storedRules.syncFileSystem();
+    }
+
+    private boolean isSharedFile(String description, String fileName) {
+        Path folder = storeFolder.toPath().toAbsolutePath().normalize();
+        Path target = folder.resolve(fileName).normalize();
+        Path resolved = null;
+        if (existsWithoutFollowingLinks(target.toFile())) {
+            try {
+                resolved = target.toRealPath();
+            } catch (IOException ignored) {
+                // A broken target is not a file that needs protecting.
+            }
+        }
+        for (Map.Entry<String, String> entry : storedRules.entries()) {
+            if (!entry.getKey().equals(description) && (entry.getValue().equals(fileName) ||
+                    (resolved != null && resolvesTo(entry.getValue(), resolved, folder)))) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    private boolean resolvesTo(String fileName, Path target, Path folder) {
+        try {
+            Path candidate = folder.resolve(fileName).normalize();
+            return existsWithoutFollowingLinks(candidate.toFile()) && candidate.toRealPath().equals(target);
+        } catch (IOException e) {
+            return false;
+        }
+    }
+
+    private void validateSaveTarget(String description, String fileName, boolean ownEntry) {
+        Path folder = storeFolder.toPath().toAbsolutePath().normalize();
+        Path target = folder.resolve(fileName).normalize();
+        if (STORED_RULES_FILE_NAME.equals(fileName) || target.equals(folder.resolve(STORED_RULES_FILE_NAME)) ||
+                !target.startsWith(folder) || !target.getParent().equals(folder)) {
+            throw unsafeSave(description, fileName);
+        }
+        if (existsWithoutFollowingLinks(target.toFile())) {
+            if (!ownEntry || Files.isSymbolicLink(target) || !Files.isRegularFile(target, LinkOption.NOFOLLOW_LINKS)) {
+                throw unsafeSave(description, fileName);
+            }
+        }
+        for (Map.Entry<String, String> entry : storedRules.entries()) {
+            if (!entry.getKey().equals(description) && entry.getValue().equals(fileName)) {
+                throw unsafeSave(description, fileName);
+            }
+        }
+    }
+
+    private StoreUpdateFailedException unsafeSave(String description, String fileName) {
+        return new StoreUpdateFailedException(String.format(
+                "Refusing to store violations for rule '%s' in unsafe or occupied file '%s'", description, fileName));
+    }
+
+    private void write(List<String> violations, File ruleDetails) {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(escape(violation)).append("\n");
+        }
+        try {
+            Files.write(ruleDetails.toPath(), builder.toString().getBytes(UTF_8));
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private String escape(String violation) {
+        return violation.replace("\n", "\\\n");
+    }
+
+    private String unescape(String violation) {
+        return violation.replace("\\\n", "\n");
+    }
+
+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        String ruleDetailsFileName = storedRules.getProperty(rule.getDescription());
+        checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
+        List<String> result = readLines(new File(storeFolder, ruleDetailsFileName).toPath().toFile());
+        log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
+        return result;
+    }
+
+    private List<String> readLines(File file) {
+        String violationsText = readStoreFile(file);
+        return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(violationsText)
+                .map(this::unescape)
+                .collect(toList());
+    }
+
+    private String readStoreFile(File file) {
+        try {
+            String result = new String(toByteArray(file), UTF_8);
+            return ensureAllUnixLineBreaks(result);
+        } catch (IOException e) {
+            throw new StoreReadException(e);
+        }
+    }
+
+    private static String ensureAllUnixLineBreaks(String string) {
+        return string.replace("\r\n", "\n").replace('\r', '\n');
+    }
+
+    private static boolean existsWithoutFollowingLinks(File file) {
+        try {
+            Files.readAttributes(file.toPath(), BasicFileAttributes.class, LinkOption.NOFOLLOW_LINKS);
+            return true;
+        } catch (IOException e) {
+            return false;
+        }
+    }
+
+    private enum IntegrityMode {
+        REPAIR, FAIL, IGNORE;
+
+        static IntegrityMode from(String value) {
+            if ("repair".equals(value)) {
+                return REPAIR;
+            }
+            if ("fail".equals(value)) {
+                return FAIL;
+            }
+            if ("ignore".equals(value)) {
+                return IGNORE;
+            }
+            throw new StoreInitializationFailedException(String.format(
+                    "Invalid value '%s' for %s; accepted values are repair, fail, and ignore",
+                    value, INTEGRITY_PROPERTY_NAME));
+        }
+    }
+
+    private static class IntegrityEntry {
+        private final String description;
+        private final String recordedName;
+        private Path recordedPath;
+        private Path resolvedPath;
+        private String resolvedFileKey;
+        private String derivedName;
+        private boolean broken;
+        private boolean empty;
+        private boolean misplaced;
+        private boolean shared;
+        private boolean colliding;
+        private boolean occupied;
+
+        IntegrityEntry(String description, String recordedName) {
+            this.description = description;
+            this.recordedName = recordedName;
+        }
+    }
+
+    private class IntegrityReport {
+        private final List<IntegrityEntry> entries;
+        private final List<Path> unownedFiles;
+
+        IntegrityReport(List<IntegrityEntry> entries, List<Path> unownedFiles) {
+            this.entries = entries;
+            this.unownedFiles = unownedFiles;
+        }
+
+        boolean hasProblems() {
+            return !unownedFiles.isEmpty() || entries.stream().anyMatch(entry -> entry.broken || entry.empty || entry.misplaced ||
+                    entry.shared || entry.colliding || entry.occupied);
+        }
+
+        String message() {
+            StringBuilder result = new StringBuilder("Violation store integrity check failed at ")
+                    .append(storeFolder.getAbsolutePath()).append(':');
+            appendEntries(result, "broken", entry -> entry.broken);
+            appendEntries(result, "resolved", entry -> entry.empty);
+            appendEntries(result, "shared", entry -> entry.shared);
+            appendFiles(result, "unowned", unownedFiles);
+            appendEntries(result, "misplaced", entry -> entry.misplaced);
+            appendEntries(result, "colliding", entry -> entry.colliding);
+            appendEntries(result, "occupied", entry -> entry.occupied);
+            return result.toString();
+        }
+
+        private void appendEntries(StringBuilder result, String condition, EntryPredicate predicate) {
+            result.append("\n").append(condition).append(':');
+            for (IntegrityEntry entry : entries) {
+                if (predicate.test(entry)) {
+                    result.append("\n  ").append(entry.description).append(" -> ").append(entry.recordedName);
+                    if (entry.misplaced) {
+                        result.append(" (derived: ").append(entry.derivedName).append(')');
+                    }
+                }
+            }
+        }
+
+        private void appendFiles(StringBuilder result, String condition, List<Path> files) {
+            result.append("\n").append(condition).append(':');
+            for (Path file : files) {
+                result.append("\n  ").append(file.getFileName());
+            }
+        }
+    }
+
+    @FunctionalInterface
+    private interface EntryPredicate {
+        boolean test(IntegrityEntry entry);
+    }
+
+    private static class FileSyncedProperties {
+        private final File propertiesFile;
+        private Properties loadedProperties;
+        private boolean initializationSuccessful;
+
+        FileSyncedProperties(File file, boolean materialize) {
+            propertiesFile = file;
+            initializationSuccessful = prepare(materialize);
+            loadedProperties = initializationSuccessful ? loadRulesFrom(propertiesFile) : null;
+        }
+
+        synchronized boolean initializationSuccessful() {
+            return initializationSuccessful;
+        }
+
+        synchronized void materialize() {
+            if (!initializationSuccessful) {
+                return;
+            }
+            if (!existsWithoutFollowingLinks(propertiesFile)) {
+                try {
+                    File directory = propertiesFile.getParentFile();
+                    if (!directory.mkdirs() && !directory.isDirectory()) {
+                        initializationSuccessful = false;
+                        return;
+                    }
+                    if (!propertiesFile.createNewFile() && !Files.isRegularFile(propertiesFile.toPath(), LinkOption.NOFOLLOW_LINKS)) {
+                        initializationSuccessful = false;
+                    }
+                } catch (IOException e) {
+                    initializationSuccessful = false;
+                }
+            }
+        }
+
+        synchronized void reload() {
+            if (!initializationSuccessful) {
+                return;
+            }
+            if (existsWithoutFollowingLinks(propertiesFile)) {
+                if (!Files.isRegularFile(propertiesFile.toPath(), LinkOption.NOFOLLOW_LINKS)) {
+                    initializationSuccessful = false;
+                } else {
+                    loadedProperties = loadRulesFrom(propertiesFile);
+                }
+            } else {
+                loadedProperties = new Properties();
+            }
+        }
+
+        private boolean prepare(boolean materialize) {
+            File directory = propertiesFile.getParentFile();
+            if (existsWithoutFollowingLinks(directory) && !directory.isDirectory()) {
+                return false;
+            }
+            if (!materialize) {
+                return true;
+            }
+            try {
+                if (!directory.mkdirs() && !directory.isDirectory()) {
+                    return false;
+                }
+                if (!existsWithoutFollowingLinks(propertiesFile) && !propertiesFile.createNewFile()) {
+                    return false;
+                }
+                return Files.isRegularFile(propertiesFile.toPath(), LinkOption.NOFOLLOW_LINKS);
+            } catch (IOException e) {
+                return false;
+            }
+        }
+
+        private Properties loadRulesFrom(File file) {
+            Properties result = new Properties();
+            if (!existsWithoutFollowingLinks(file)) {
+                return result;
+            }
+            try (FileInputStream inputStream = new FileInputStream(file)) {
+                result.load(inputStream);
+            } catch (IOException e) {
+                throw new StoreInitializationFailedException(e);
+            }
+            return result;
+        }
+
+        synchronized boolean containsKey(String propertyName) {
+            return loadedProperties.containsKey(ensureUnixLineBreaks(propertyName));
+        }
+
+        synchronized String getProperty(String propertyName) {
+            return loadedProperties.getProperty(ensureUnixLineBreaks(propertyName));
+        }
+
+        synchronized List<Map.Entry<String, String>> entries() {
+            List<Map.Entry<String, String>> result = new ArrayList<>();
+            for (String key : loadedProperties.stringPropertyNames()) {
+                result.add(new java.util.AbstractMap.SimpleImmutableEntry<>(key, loadedProperties.getProperty(key)));
+            }
+            return result;
+        }
+
+        synchronized void setInMemory(String key, String value) {
+            loadedProperties.setProperty(ensureUnixLineBreaks(key), ensureUnixLineBreaks(value));
+        }
+
+        synchronized void removeInMemory(String key) {
+            loadedProperties.remove(ensureUnixLineBreaks(key));
+        }
+
+        synchronized String putIfAbsent(String key, String value) {
+            String normalizedKey = ensureUnixLineBreaks(key);
+            String existing = loadedProperties.getProperty(normalizedKey);
+            if (existing != null) {
+                return existing;
+            }
+            loadedProperties.setProperty(normalizedKey, ensureUnixLineBreaks(value));
+            syncFileSystem();
+            return null;
+        }
+
+        synchronized void syncFileSystem() {
+            sync(false);
+        }
+
+        synchronized void syncFileSystemAsInitialization() {
+            sync(true);
+        }
+
+        private void sync(boolean initialization) {
+            materialize();
